bool visited[100005];
int is_bridge[100005][100005];
map<pair<int, int>, int> edge_index;

void dfs(int u, int p) {
    visited[u] = true;
    disc[u] = low[u] = timer++;
    for (int v : adj[u]) {
        if (v == p) continue;
        if (visited[v]) {
            low[u] = min(low[u], disc[v]);
        } else {
            dfs(v, u);
            low[u] = min(low[u], low[v]);
            if (low[v] > disc[u]) {
                is_bridge[u][v] = 1;
                is_bridge[v][u] = 1;
            }
        }
    }
}

