    }
    vector<long long> fact(sum + 1, 1);
    vector<long long> inv_fact(sum + 1, 1);
    for(long long i = 2; i <= sum; ++i){
        fact[i] = fact[i - 1] * i % MOD;
        inv_fact[i] = inv_fact[i - 1] * pow(i, MOD - 2, MOD) % MOD;
    }
