            int dx = points[i].first - points[j].first;
            int dy = points[i].second - points[j].second;
            int midX = points[i].first - dx / 2;
            int midY = points[i].second - dy / 2;
            if (dx % 2 == 0 && dy % 2 == 0) {
                result += count[midX][midY];
            }
            count[points[j].first + dx / 2][points[j].second + dy / 2]++;
        }
    }

    cout << result << endl;
    return 0;
}

