                auto it = online.begin();
                if(t[id-1] > (*it).first){
                    isOnline[(*it).second] = false;
                    isOnline[id] = true;
                    online.erase(it);
                    online.insert({t[id-1], id});
                }
            }
        }else{
            if(isOnline[id]) cout << "YES\n";
            else cout << "NO\n";
        }
    }
}

