int main(){
    string s;
    cin >> s;
    int n = s.size();
    vector<long long> dp(n + 1, 0);
    dp[0] = 1;
    for(int i = 0; i < n; i++){
        dp[i + 1] = dp[i];
        if(i > 0 && s[i] == s[i - 1]){
            dp[i + 1] = (dp[i + 1] + dp[i - 1]) % MOD;
        }
    }
    cout << dp[n] << endl;
}

#include <bits/stdc++.h>
using namespace std;

const int MAXN = 1005, MAXM = 200005;

vector<int> adj[MAXN], radj[MAXN];
bool vis[MAXN];
stack<int> stk;
int sccid[MAXN], scccnt;

void dfs(int u) {
    vis[u] = true;
    for (int v : adj[u]) {
        if (!vis[v]) dfs(v);
    }
    stk.push(u);
}

void rdfs(int u, int id) {
    vis[u] = true;
    sccid[u] = id;
    for (int v : radj[u]) {
        if (!vis[v]) rdfs(v, id);
    }
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    int N, M;
    cin >> N >> M;
    vector<pair<int, int>> edges(M);
    for(int i=0; i<M; i++){
        cin >> edges[i].first >> edges[i].second;
        adj[edges[i].first].push_back(edges[i].second);
        radj[edges[i].second].push_back(edges[i].first);
    }
    for(int i=1; i<=N; i++){
        if(!vis[i]) dfs(i);
    }
    memset(vis, false, sizeof(vis));
    while(!stk.empty()){
        int u = stk.top();
        stk.pop();
        if(!vis[u]){
            rdfs(u, scccnt++);
        }
    }
    vector<int> in(scccnt, 0), out(scccnt, 0);
    for(auto [u, v] : edges){
        if(sccid[u] != sccid[v]){
            out[sccid[u]]++;
            in[sccid[v]]++;
        }
    }
    for(auto [u, v] : edges){
        int su = sccid[u], sv = sccid[v];
        if(su == sv){
            cout << "same\n";
        }
        else{
            bool change = false;
            if(out[su] == 1 && in[sv] == 1) change = true;
            if(out[sv] == 0) change = true;
            if(in[su] == 0) change = true;
            cout << (change ? "diff\n" : "same\n");
        }
    }
}

