        A[P[i]].push_back(i);
    }
    vector<int> ans(N);
    int last = -1;
    for(int i=1;i<=N;i++){
        if(A[i].empty()) continue;
        int idx = A[i].back();
        A[i].pop_back();
        while(!A[i].empty()){
            int nidx = A[i].back();
            if(idx - nidx >= K){
                idx = nidx;
                A[i].pop_back();
            }
            else break;
        }
        last = idx;
        ans[idx] = i;
    }
    int num = 1;
    for(int i=0;i<N;i++){
        if(ans[i] == 0){
            while(!A[num].empty()) num++;
            ans[i] = num++;
        }
    }
    for(auto &x: ans) cout << x << "\n";
}

