using namespace std;

void flip(int &cell) {
    cell = 1 - cell;
}

void process_grid(vector<vector<int>> &grid) {
    int n = grid.size();
    vector<vector<int>> result(n, vector<int>(n, 0));

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] == 1) {
                result[i][j] = 1;
                if (i > 0) flip(grid[i - 1][j]);
                if (i < n - 1) flip(grid[i + 1][j]);
                if (j > 0) flip(grid[i][j - 1]);
                if (j < n - 1) flip(grid[i][j + 1]);
                flip(grid[i][j]);
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (grid[i][j] == 1) {
                result[i][j] = 1;
                if (i > 0) flip(grid[i - 1][j]);
                if (i < n - 1) flip(grid[i + 1][j]);
                if (j > 0) flip(grid[i][j - 1]);
                if (j < n - 1) flip(grid[i][j + 1]);
                flip(grid[i][j]);
            }
        }
    }

    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            cout << result[i][j] << (j == n - 1 ? '\n' : ' ');
        }
    }
}

