}

#include <bits/stdc++.h>
using namespace std;

struct State {
    int board[9];
    int empty;
    int cost;
    bool operator<(const State& o) const {
        return cost > o.cost;
    }
};

int dr[] = {-1, 1, 0, 0};
int dc[] = {0, 0, -1, 1};
int cost_hv[] = {0, 0, 0, 0};

int heuristic(const State& state, const State& goal) {
    int h = 0;
    for (int i = 0; i < 9; i++) {
        if (state.board[i] != 0 && state.board[i] != goal.board[i]) {
            for (int j = 0; j < 9; j++) {
                if (goal.board[j] == state.board[i]) {
                    int r1 = i / 3, c1 = i % 3;
                    int r2 = j / 3, c2 = j % 3;
                    int dh = min(abs(r1 - r2), 3 - abs(r1 - r2));
                    int dv = min(abs(c1 - c2), 3 - abs(c1 - c2));
                    h += dh * cost_hv[2] + dv * cost_hv[3];
                }
            }
        }
    }
    return h;
}

int manhattan_distance(int a, int b) {
    int x1 = a / 3, y1 = a % 3;
    int x2 = b / 3, y2 = b % 3;
    return min(abs(x1 - x2), 3 - abs(x1 - x2)) + min(abs(y1 - y2), 3 - abs(y1 - y2));
}

int get_empty(const vector<int>& board) {
    for (int i = 0; i < 9; i++) {
        if (board[i] == 0) return i;
    }
    return -1;
}

int encode(const vector<int>& board) {
    int code = 0;
    for (int num : board) {
        code = code * 9 + num;
    }
    return code;
}

int solve(const State& start, const State& goal) {
    priority_queue<State> pq;
    pq.push(start);
    unordered_map<int, int> visited;
    visited[encode(vector<int>(start.board, start.board + 9))] = 0;

    while (!pq.empty()) {
        State current = pq.top();
        pq.pop();

        if (memcmp(current.board, goal.board, sizeof(current.board)) == 0) {
            return current.cost;
        }

        int x = current.empty / 3, y = current.empty % 3;
        for (int dir = 0; dir < 4; dir++) {
            int nx = (x + dr[dir] + 3) % 3;
            int ny = (y + dc[dir] + 3) % 3;
            int nempty = nx * 3 + ny;
            State next = current;
            next.board[current.empty] = next.board[nempty];
            next.board[nempty] = 0;
            next.empty = nempty;
            next.cost += dir < 2 ? cost_hv[0] : cost_hv[1];

            int code = encode(vector<int>(next.board, next.board + 9));
            if (visited.find(code) == visited.end() || visited[code] > next.cost) {
                visited[code] = next.cost;
                pq.push(next);
            }
        }
    }
    return -1;
}

int main() {
    while (true) {
        int ch, cv;
        cin >> ch >> cv;
        if (ch == 0 && cv == 0) break;
        cost_hv[0] = cost_hv[2] = ch;
        cost_hv[1] = cost_hv[3] = cv;

        State start, goal;
        for (int i = 0; i < 9; i++) {
            int x;
            cin >> x;
            start.board[i] = x;
            if (x == 0) start.empty = i;
        }
        for (int i = 0; i < 9; i++) {
            int x;
            cin >> x;
            goal.board[i] = x;
            if (x == 0) goal.empty = i;
        }

        start.cost = 0;
        cout << solve(start, goal) << "\n";
    }
}

#include <bits/stdc++.h>
using namespace std;

int dx[] = {0, 0, 1, -1};
int dy[] = {1, -1, 0, 0};

struct State {
    int x, y, time, dir;
    State(int x, int y, int time, int dir) : x(x), y(y), time(time), dir(dir) {}
};

bool isValid(int x, int y, int R, int C, vector<string> &grid) {
    return x >= 0 && x < R && y >= 0 && y < C && grid[x][y] != '#';
}

void paint(vector<string> &grid, int x, int y, int dir) {
    for (int d = 1; d <= 3; d++) {
        int nx = x + dx[dir] * d;
        int ny = y + dy[dir] * d;
        if (!isValid(nx, ny, grid.size(), grid[0].size(), grid)) break;
        if (grid[nx][ny] == 'x') break;
        if (grid[nx][ny] == '.') grid[nx][ny] = 'o';
    }
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int R, C;
    cin >> R >> C;
    vector<string> grid(R);
    for(auto &row: grid) cin >> row;
    int startX, startY;
    int goalX, goalY;
    for(int i=0;i<R;i++){
        for(int j=0;j<C;j++){
            if(grid[i][j] == 'S'){
                startX = i, startY = j;
                grid[i][j] = '.';
            }
            else if(grid[i][j] == 'G'){
                goalX = i, goalY = j;
                grid[i][j] = '.';
            }
        }
    }
    priority_queue<tuple<int, int, int, int, int>, vector<tuple<int, int, int, int, int>>, greater<tuple<int, int, int, int, int>>> pq;
    pq.emplace(0, startX, startY, 0, 0);
    unordered_set<string> visited;
    string startKey = to_string(startX) + "," + to_string(startY) + "," + to_string(0);
    visited.insert(startKey);
    while(!pq.empty()){
        auto [time, x, y, prevDir, paintTime] = pq.top();
        pq.pop();
        if(x == goalX && y == goalY)return cout << time, 0;
        for(int k=0;k<4;k++){
            int nx = x + dx[k];
            int ny = y + dy[k];
            if(isValid(nx, ny, R, C, grid)){
                string key = to_string(nx) + "," + to_string(ny) + "," + to_string(time);
                if(visited.find(key) == visited.end()){
                    visited.insert(key);
                    int cost = grid[nx][ny] == '.' ? 2 : 1;
                    if(paintTime == 2){
                        pq.emplace(time + cost, nx, ny, k, 0);
                    }
                    else{
                        pq.emplace(time + cost, nx, ny, k, paintTime + 1);
                    }
                }
            }
        }
        if(paintTime < 2){
            vector<string> tempGrid = grid;
            paint(tempGrid, x, y, prevDir);
            string key = to_string(x) + "," + to_string(y) + "," + to_string(time + 2);
            if(visited.find(key) == visited.end()){
                visited.insert(key);
                pq.emplace(time + 2, x, y, prevDir, paintTime + 1);
            }
        }
    }
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

double heron(double a, double b, double c) {
    double s = (a + b + c) / 2.0;
    return sqrt(s * (s - a) * (s - b) * (s - c));
}

double tetrahedron_volume(double a, double b, double c, double d, double e, double f) {
    double S1 = heron(a, b, c);
    double S2 = heron(d, e, f);
    double K1 = sqrt(4.0 * pow(S1, 2) - pow(a, 2) - pow(b, 2) - pow(c, 2) + 2.0 * a * b * c * cos(acos((pow(a, 2) + pow(b, 2) - pow(c, 2)) / (2.0 * a * b))));
    double K2 = sqrt(4.0 * pow(S2, 2) - pow(d, 2) - pow(e, 2) - pow(f, 2) + 2.0 * d * e * f * cos(acos((pow(d, 2) + pow(e, 2) - pow(f, 2)) / (2.0 * d * e))));
    double V = (2.0 * S1 * S2 * cos(acos((pow(S1, 2) + pow(S2, 2) - pow(K1 * K2, 2)) / (2.0 * S1 * S2)))) / 12.0;
    return V;
}

