                    if (sticks[i] + sticks[j] > sticks[k] && sticks[i] + sticks[k] > sticks[j] && sticks[j] + sticks[k] > sticks[i]) {
                        for (int l = 0; l < n; ++l) {
                            if (l != i && l != j && l != k) {
