        for(int j=0;j<=m;j++){
            dp[i][j] = -1e9;
        }
    }
    dp[0][0] = 0;

    for(int i=1;i<=n;i++){
        for(int j=0;j<=m;j++){
            dp[i][j] = dp[i-1][j];
            int cost = 0;
            int profit = 0;
            int mx = j;
            vector<int> cnt(m + n + 1, 0);
            for(int k=i-1;k>=0;k--){
