        for(const auto& s1: stones) {
            bool hit = false;
            for(const auto& s2: stones) {
                if(s1 != s2 && canHit(s1, s2, m)) {
                    hit = true;
                    break;
                }
            }
            if(hit) {
                afraid++;
                break;
            }
        }
    }
    cout << afraid;
    return 0;
}

