bool check(vector<int>& s, int start) {
    unordered_set<int> visited;
    int pos = start;
    while (true) {
        if (pos == 0) return true;
        if (visited.find(pos) != visited.end()) return false;
        visited.insert(pos);
        int next_pos = -1;
        for (int step : s) {
            int new_pos = (pos + step) % n;
            if (next_pos == -1 || (abs(new_pos - pos) < abs(next_pos - pos))) {
                next_pos = new_pos;
            }
        }
        pos = next_pos;
    }
}

