    for (int i = 0; i < 2 * N; i += 2) {
        if (heights[i] == heights[i + 1]) {
            cout << 0;
            return 0;
        }
        ans = (ans * (i + 1)) % MOD;
    }
    long long inv_fact = modpow(2, N, MOD);
    inv_fact = modpow(inv_fact, MOD - 2, MOD);
    ans = (ans * inv_fact) % MOD;
    cout << ans;
}

