const int INF = 1e9;
const int MAXN = 110;

enum {HOME, HALL, CAKE, LAND};

struct Edge {
    int to, weight;
};

vector<Edge> adj[MAXN];
int cake_calories[7];
int dp[1 << 7][MAXN];

int get_id(char type, int num) {
    if (type == 'H') return HOME;
    if (type == 'D') return HALL;
    if (type == 'C') return CAKE + num;
    return LAND + num;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    int m, n, k, d;
    while(cin >> m >> n >> k >> d, m || n || k || d){
        for(int i=0;i<(1<<m);i++){
            for(int j=0;j<MAXN;j++){
                dp[i][j] = -INF;
            }
        }
        dp[0][HOME] = 0;
        for(int i=0;i<m;i++){
            cin >> cake_calories[i];
        }
        for(int i=0;i<MAXN;i++){
            adj[i].clear();
        }
        for(int i=0;i<d;i++){
            char s_t, t_t;
            int s_n, t_n, w;
            cin >> s_t >> s_n >> t_t >> t_n >> w;
            int s = get_id(s_t, s_n);
            int t = get_id(t_t, t_n);
            adj[s].push_back({t, w});
            adj[t].push_back({s, w});
        }
        queue<pair<int,int>> q;
        q.push({0, HOME});
        while(!q.empty()){
            int mask = q.front().first;
            int node = q.front().second;
            q.pop();
            for(auto& e : adj[node]){
                int next_node = e.to;
                int next_mask = mask;
                int cost = dp[mask][node] - e.weight * k;
                if(next_node >= CAKE && next_node < CAKE + m){
                    next_mask |= (1 << (next_node - CAKE));
                    cost += cake_calories[next_node - CAKE];
                }
                if(cost > dp[next_mask][next_node]){
                    dp[next_mask][next_node] = cost;
                    q.push({next_mask, next_node});
                }
            }
        }
        int ans = -INF;
        for(int i=0;i<(1<<m);i++){
            ans = max(ans, dp[i][HALL]);
        }
        cout << ans << "\n";
    }
}

#include <bits/stdc++.h>
using namespace std;

const int MAXN = 100005, MAXLOG = 20;
vector<pair<int, int>> adj[MAXN];
int depth[MAXN], parent[MAXN][MAXLOG];
int dist[MAXN][MAXLOG];

void dfs(int u, int p, int d) {
    parent[u][0] = p;
    depth[u] = d;
    for(auto e: adj[u]) {
        int v = e.first, w = e.second;
        if(v != p) {
            dist[v][0] = w;
            dfs(v, u, d + 1);
        }
    }
}

void init_lca(int n) {
    for(int k = 1; k < MAXLOG; k++) {
        for(int v = 1; v <= n; v++) {
            if(parent[v][k-1] != -1) {
                int par = parent[v][k-1];
                parent[v][k] = parent[par][k-1];
                dist[v][k] = max(dist[v][k-1], dist[par][k-1]);
            }
        }
    }
}

int query(int u, int v) {
    int res = 0;
    if(depth[u] > depth[v]) swap(u, v);
    for(int k = MAXLOG-1; k >= 0; k--) {
        if(depth[v] - (1 << k) >= depth[u]) {
            res = max(res, dist[v][k]);
            v = parent[v][k];
        }
    }
    if(u == v) return res;
    for(int k = MAXLOG-1; k >= 0; k--) {
        if(parent[u][k] != parent[v][k]) {
            res = max({res, dist[u][k], dist[v][k]});
            u = parent[u][k];
            v = parent[v][k];
        }
    }
    res = max({res, dist[u][0], dist[v][0]});
    return res;
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(NULL);
    int n, q;
    cin >> n >> q;
    for(int i = 0; i < n-1; i++) {
        int u, v, w;
        cin >> u >> v >> w;
        adj[u].emplace_back(v, w);
        adj[v].emplace_back(u, w);
    }
    memset(parent, -1, sizeof(parent));
    dfs(1, -1, 0);
    init_lca(n);
    while(q--) {
        int a, b, c;
        cin >> a >> b >> c;
        int ab = query(a, b);
        int ac = query(a, c);
        int bc = query(b, c);
        int res = max({ab, ac, bc});
        cout << res << "\n";
    }
    return 0;
}

