        }
        double tg, tw;
        cin >> tg >> tw;
        Point guard, girl;
        cin >> guard.x >> guard.y >> girl.x >> girl.y;
        cout << fixed << setprecision(10) << solve(n, pool, tg, tw, guard, girl) << '\n';
    }
}

