void dfs(int u, int p) {
    dp[u][0] = 1.0 - prob[u];
    dp[u][1] = prob[u];
    for (int v : G[u]) {
        if (v == p) continue;
        dfs(v, u);
        dp[u][0] *= (dp[v][0] + dp[v][1]);
        dp[u][1] *= dp[v][1];
    }
}

