    vector<tuple<ld, ld, ld, ld>> tanks(n);
    for (auto& [x, y, a, w] : tanks) {
        cin >> x >> y >> a >> w;
    }
    ld k;
    cin >> k;

    ld lo = 0, hi = 1e5;
    while (hi - lo > EPS) {
        ld mid = (lo + hi) / 2;
        if (check(mid, ax, ay, bx, by, tanks, k)) {
            hi = mid;
        } else {
            lo = mid;
        }
    }
    cout << fixed << setprecision(4) << lo;
}

