#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

struct Node {
    ll sum, inc, lazy;

    Node() : sum(0), inc(0), lazy(0) {}

    void apply(ll l, ll r, ll v) {
        sum += v * (r - l + 1);
        lazy += v;
        inc += v;
    }

    void push(ll l, ll m, Node &left, Node &right) {
        left.apply(l, m, lazy);
        right.apply(m + 1, r, lazy);
        lazy = 0;
    }
};

void build(int n, int s, int t, vector<Node> &tree, vector<ll> &arr) {
    if (s == t) {
        tree[n].sum = arr[s];
        return;
    }
    int m = (s + t) / 2;
    build(2 * n, s, m, tree, arr);
    build(2 * n + 1, m + 1, t, tree, arr);
    tree[n].sum = tree[2 * n].sum + tree[2 * n + 1].sum;
}

void update(int n, int s, int t, int l, int r, ll v, vector<Node> &tree) {
    if (l > t || r < s) {
        return;
    }
    if (l <= s && t <= r) {
        tree[n].apply(s, t, v);
        return;
    }
    int m = (s + t) / 2;
    tree[n].push(s, m, tree[2 * n], tree[2 * n + 1]);
    update(2 * n, s, m, l, r, v, tree);
    update(2 * n + 1, m + 1, t, l, r, v, tree);
    tree[n].sum = tree[2 * n].sum + tree[2 * n + 1].sum;
}

ll query(int n, int s, int t, int l, int r, vector<Node> &tree, vector<ll> &delta, int lvl = 0) {
    if (l > t || r < s) {
        return 0;
    }
    if (l <= s && t <= r) {
        return tree[n].sum + tree[n].inc + delta[lvl] * (t - s + 1);
    }
    int m = (s + t) / 2;
    tree[n].push(s, m, tree[2 * n], tree[2 * n + 1]);
    return query(2 * n, s, m, l, r, tree, delta, lvl + 1) +
           query(2 * n + 1, m + 1, t, l, r, tree, delta, lvl + 1);
}

int main(){
    ios::sync_with_stdio(false);
    cin.tie(0);
    int N, Q;
    cin >> N >> Q;
    vector<ll> a(2*N), b(2*N);
    for(int i=0;i<2*N;i++) cin >> a[i];
    for(int i=0;i<2*N;i++) cin >> b[i];
    vector<Node> tree(4*2*N);
    vector<ll> arr(2*N);
    for(int i=0;i<2*N;i++) arr[i] = a[i]+b[i];
    build(1,0,2*N-1,tree,arr);
    auto go = [&](int d, int lo, int hi, int lvl){
        if(lo > hi) return;
        if(lo == hi){
            if(arr[lo] == a[lo]){
                delta[lvl] += b[lo] - a[lo];
            }
            return;
        }
        int mid = (lo+hi)/2;
        if(d == 0){
            go(0,lo,mid,lvl+1);
            go(1,mid+1,hi,lvl+1);
        }
        else{
            go(1,lo,mid,lvl+1);
            go(0,mid+1,hi,lvl+1);
        }
    };
    vector<ll> delta(2*N);
    go(0,0,2*N-1,0);
    while(Q--){
        int p;
        ll x, y;
        cin >> p >> x >> y;
        p--;
        ll diff = x + y - a[p] - b[p];
        a[p] = x;
        b[p] = y;
        update(1,0,2*N-1,p,p,diff,tree);
        auto score = [&](int d, int lo, int hi, int lvl){
            if(lo > hi) return 0LL;
            if(lo == hi){
                if(arr[lo] == a[lo]){
                    return b[lo] + delta[lvl] + tree[1].inc;
                }
                return a[lo] + delta[lvl] + tree[1].inc;
            }
            int mid = (lo+hi)/2;
            if(d == 0){
                auto l = score(0,lo,mid,lvl+1);
                auto r = score(1,mid+1,hi,lvl+1);
                return l + r;
            }
            else{
                auto l = score(1,lo,mid,lvl+1);
                auto r = score(0,mid+1,hi,lvl+1);
                return l + r;
            }
        };
        ll ans = score(0,0,2*N-1,0);
        cout << ans << "\n";
    }
}

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

struct Town {
    int x, y, id;
};

struct Edge {
    int u, v;
    int cost;
};

bool compareX(const Town& a, const Town& b) {
    return a.x < b.x || (a.x == b.x && a.y < b.y);
}

bool compareY(const Town& a, const Town& b) {
    return a.y < b.y || (a.y == b.y && a.x < b.x);
}

int find(int u, vector<int>& parent) {
    if (u == parent[u]) return u;
    return parent[u] = find(parent[u], parent);
}

void merge(int u, int v, vector<int>& parent, vector<int>& sz) {
    u = find(u, parent);
    v = find(v, parent);
    if (u == v) return;
    if (sz[u] < sz[v]) swap(u, v);
    parent[v] = u;
    sz[u] += sz[v];
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    int N;
    cin >> N;
    vector<Town> towns(N);
    for (int i = 0; i < N; i++) {
        cin >> towns[i].x >> towns[i].y;
        towns[i].id = i;
    }
    vector<Town> sortedX = towns;
    vector<Town> sortedY = towns;
    sort(sortedX.begin(), sortedX.end(), compareX);
    sort(sortedY.begin(), sortedY.end(), compareY);
    vector<Edge> edges;
    for (int i = 0; i < N - 1; i++) {
        edges.push_back({sortedX[i].id, sortedX[i+1].id, abs(sortedX[i].x - sortedX[i+1].x)});
        edges.push_back({sortedY[i].id, sortedY[i+1].id, abs(sortedY[i].y - sortedY[i+1].y)});
    }
    sort(edges.begin(), edges.end(), [](const Edge& a, const Edge& b) {
        return a.cost < b.cost;
    });
    vector<int> parent(N);
    vector<int> sz(N, 1);
    for (int i = 0; i < N; i++) parent[i] = i;
    int totalCost = 0;
    for (const auto& edge : edges) {
        int u = edge.u;
        int v = edge.v;
        int cost = edge.cost;
        if (find(u, parent) != find(v, parent)) {
            merge(u, v, parent, sz);
            totalCost += cost;
        }
    }
    cout << totalCost << "\n";
}

#include <bits/stdc++.h>
using namespace std;

const int MAXN = 105;
const int INF = 1e9;

vector<pair<int, int>> adj[MAXN];
int dist[MAXN][MAXN];

void floydWarshall(int n) {
    for (int i = 1; i <= n; ++i) {
        for (int j = 1; j <= n; ++j) {
            if (i != j) dist[i][j] = INF;
            else dist[i][j] = 0;
        }
    }
    for (int i = 1; i <= n; ++i) {
        for (auto edge : adj[i]) {
            int v = edge.first, w = edge.second;
            dist[i][v] = min(dist[i][v], w);
        }
    }
    for (int k = 1; k <= n; ++k) {
        for (int i = 1; i <= n; ++i) {
            for (int j = 1; j <= n; ++j) {
                dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j]);
            }
        }
    }
}

int main(){
    int n, m;
    cin >> n >> m;
    for(int i=0; i<m; i++){
        int u, v, c;
        cin >> u >> v >> c;
        adj[u].push_back({v, c});
        adj[v].push_back({u, c});
    }
    floydWarshall(n);
    int ans = 0;
    for(int i=1; i<=n; i++){
        for(auto edge : adj[i]){
            int v = edge.first, c = edge.second;
            bool isShortestPath = false;
            for(int j=1; j<=n; j++){
                for(int k=1; k<=n; k++){
                    if(j != k && dist[j][k] == dist[j][i] + c + dist[v][k]){
                        isShortestPath = true;
                        break;
                    }
                }
                if(isShortestPath) break;
            }
            if(!isShortestPath) ans++;
        }
    }
    cout << ans/2;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const ll MOD = 1e9 + 7;

int main(){
    ll N, M, K;
    cin >> N >> M >> K;
    ll ans = 0;
    for(ll na = 0; na <= N; na++){
        for(ll nb = 0; nb <= M; nb++){
            for(ll nc = 0; nc <= K; nc++){
                ll total = na + nb + nc;
                if(total == 0) continue;
                ll cnt[3] = {na, nb, nc};
                ll cnta = 0, cntb = 0, cntc = 0;
                ll turn = 0;
                bool win[3] = {false, false, false};
                for(ll i = 0; i < total; i++){
                    if(cnt[turn] == 0){
                        win[turn] = true;
                        break;
                    }
                    cnt[turn]--;
                    if(turn == 0) cnta++;
                    if(turn == 1) cntb++;
                    if(turn == 2) cntc++;
                    turn = cnta - cntb >= 0 ? (cnta - cntc >= 0 ? 0 : 2) : (cntb - cntc >= 0 ? 1 : 2);
                }
                if(win[0]){
                    ll ways = 1;
                    ways = ways * (ll)pow(3, total - (na + nb + nc), MOD) % MOD;
                    ways = ways * (ll)pow(3, N - na, MOD) % MOD;
                    ways = ways * (ll)pow(3, M - nb, MOD) % MOD;
                    ways = ways * (ll)pow(3, K - nc, MOD) % MOD;
                    ans = (ans + ways) % MOD;
                }
            }
        }
    }
    cout << ans;
}
